import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, lineTotal, lineDiscount, lineVat, invoiceTotals, addLine, removeLine, issueInvoice } from '../src/invoices.js';

test('createInvoice creates a draft invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 2 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.customerId, 'C-001');
  assert.equal(r.value.issueDate, '2026-10-07');
  assert.equal(r.value.status, 'draft');
  assert.equal(r.value.lines.length, 1);
});

test('createInvoice enriches lines with product details', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 3 }],
  });
  assert.equal(r.ok, true);
  const line = r.value.lines[0];
  assert.equal(line.sku, 'DEV-HOUR');
  assert.equal(line.name, 'Development (hour)');
  assert.equal(line.qty, 3);
  assert.equal(line.unitPrice, 9500);
  assert.equal(line.vatRate, 21);
});

test('createInvoice handles multiple lines', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-01-15',
    lines: [
      { sku: 'LOGO-PACK', qty: 1 },
      { sku: 'ICON-SET', qty: 2 },
    ],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines.length, 2);
  assert.equal(r.value.lines[0].sku, 'LOGO-PACK');
  assert.equal(r.value.lines[1].sku, 'ICON-SET');
});

test('createInvoice returns CUSTOMER_NOT_FOUND for unknown customer', () => {
  const r = createInvoice({
    customerId: 'C-999',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  assert.deepEqual(r, { ok: false, error: 'CUSTOMER_NOT_FOUND' });
});

test('createInvoice returns DATE_INVALID for malformed date', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '10/07/2026',
      lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    }),
    { ok: false, error: 'DATE_INVALID' }
  );
});

test('createInvoice returns DATE_INVALID for invalid date', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-02-30',
      lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    }),
    { ok: false, error: 'DATE_INVALID' }
  );
});

test('createInvoice returns DATE_INVALID for missing date', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '',
      lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    }),
    { ok: false, error: 'DATE_INVALID' }
  );
});

test('createInvoice returns NO_LINES for empty lines array', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [],
  });
  assert.deepEqual(r, { ok: false, error: 'NO_LINES' });
});

test('createInvoice returns QTY_INVALID for zero quantity', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 0 }],
  });
  assert.deepEqual(r, { ok: false, error: 'QTY_INVALID' });
});

test('createInvoice returns QTY_INVALID for negative quantity', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: -5 }],
  });
  assert.deepEqual(r, { ok: false, error: 'QTY_INVALID' });
});

test('createInvoice returns QTY_INVALID for non-integer quantity', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1.5 }],
  });
  assert.deepEqual(r, { ok: false, error: 'QTY_INVALID' });
});

test('createInvoice returns UNKNOWN_SKU for invalid SKU', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'FAKE-SKU', qty: 1 }],
  });
  assert.deepEqual(r, { ok: false, error: 'UNKNOWN_SKU' });
});

test('createInvoice does not mutate the input', () => {
  const input = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 2 }],
  };
  const inputCopy = JSON.parse(JSON.stringify(input));
  createInvoice(input);
  assert.deepEqual(input, inputCopy);
});

test('createInvoice works with VAT-exempt items', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'WORKSHOP-DAY', qty: 1 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines[0].vatRate, 0);
});

test('createInvoice works with different VAT rates', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 1 },
      { sku: 'PRINT-A4', qty: 100 },
    ],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines[0].vatRate, 21);
  assert.equal(r.value.lines[1].vatRate, 9);
});

test('lineTotal calculates qty times unitPrice', () => {
  const line = { sku: 'DEV-HOUR', name: 'Development (hour)', qty: 5, unitPrice: 9500, vatRate: 21 };
  assert.equal(lineTotal(line), 47500);
});

test('lineTotal works for qty of 1', () => {
  const line = { sku: 'LOGO-PACK', name: 'Logo package', qty: 1, unitPrice: 120000, vatRate: 21 };
  assert.equal(lineTotal(line), 120000);
});

test('lineTotal works for large quantities', () => {
  const line = { sku: 'PRINT-A4', name: 'Printed flyer A4 (each)', qty: 10000, unitPrice: 37, vatRate: 9 };
  assert.equal(lineTotal(line), 370000);
});

test('invoiceTotals sums all line totals', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'DEV-HOUR', name: 'Development (hour)', qty: 2, unitPrice: 9500, vatRate: 21, discountPercent: 0 },
      { sku: 'LOGO-PACK', name: 'Logo package', qty: 1, unitPrice: 120000, vatRate: 21, discountPercent: 0 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 19000 + 120000);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, Math.round(139000 * 21 / 100));
  assert.equal(totals.total, 139000 + Math.round(139000 * 21 / 100));
});

test('invoiceTotals with single line', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [{ sku: 'DEV-HOUR', name: 'Development (hour)', qty: 3, unitPrice: 9500, vatRate: 21, discountPercent: 0 }],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 28500);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, Math.round(28500 * 21 / 100));
  assert.equal(totals.total, 28500 + Math.round(28500 * 21 / 100));
});

test('invoiceTotals with multiple lines and different VAT rates', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'DEV-HOUR', name: 'Development (hour)', qty: 1, unitPrice: 9500, vatRate: 21, discountPercent: 0 },
      { sku: 'PRINT-A4', name: 'Printed flyer A4 (each)', qty: 100, unitPrice: 37, vatRate: 9, discountPercent: 0 },
      { sku: 'WORKSHOP-DAY', name: 'Brand workshop (day, VAT exempt)', qty: 1, unitPrice: 60000, vatRate: 0, discountPercent: 0 },
