    issueDate: '2026-10-07',
    status: 'issued',
    lines: [{ sku: 'DEV-HOUR', name: 'Development (hour)', qty: 1, unitPrice: 100000, vatRate: 21, discountPercent: 0 }],
  };
  const text = renderInvoiceText(invoice);
  const vatIndex = text.indexOf('VAT: €2,100.00');
  const totalIndex = text.indexOf('Total: €12,100.00');
  assert.ok(vatIndex > 0);
  assert.ok(totalIndex > vatIndex);
});

test('renderInvoiceText shows subtotal and discount when they apply', () => {
  const invoice = {
    number: 'INV-2026-0001',
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'issued',
    lines: [{ sku: 'DEV-HOUR', name: 'Development (hour)', qty: 1, unitPrice: 10000, vatRate: 21, discountPercent: 10 }],
  };
  const text = renderInvoiceText(invoice);
  assert.ok(text.includes('Subtotal: €100.00'));
  assert.ok(text.includes('Discount: -€10.00'));
  assert.ok(text.includes('VAT: €18.90'));
});
